61	// UpdateCircuit modifies a draft circuit version. It must target an existing,
62	// unfrozen version explicitly: unknown versions yield ErrNotFound and frozen
63	// versions yield ErrFrozen. On success the counts and description are
64	// replaced as one atomic change; partial updates can never be observed.
65	//
66	// This is the whole-record replacement entry point: the three counts and the
67	// description carried by c override the stored record outright (zero values
68	// included). Field-by-field editing with omitted-field preservation lives in
69	// UpdateCircuitPartial; both entry points run the same draft-update rules
70	// through the circuitMutation helpers below.
71	func (s *Store) UpdateCircuit(c Circuit) (Circuit, error) {
72		if err := validateCircuitKey(c.Name, c.Version); err != nil {
73			return Circuit{}, err
74		}
75		mutation := circuitMutation{
76			Constraints:   c.Constraints,
77			PublicInputs:  c.PublicInputs,
78			PrivateInputs: c.PrivateInputs,
79			Description:   c.Description,
80		}
81		// Whole replacement judges the supplied counts before the target is
82		// looked up, so an illegal replacement reports invalid argument even for
83		// unknown or frozen versions.
84		if err := validateMutationCounts(mutation); err != nil {
85			return Circuit{}, err
86		}
87	
88		var result Circuit
89		err := s.withLock(func() (bool, error) {
90			existing := findCircuit(s.data.Circuits, c.Name, c.Version)
91			if existing == nil {
92				return false, notFoundf("circuit %q version %d does not exist", c.Name, c.Version)
93			}
94			if existing.Frozen {
95				return false, frozenf("circuit %q version %d is frozen and its description cannot be modified", c.Name, c.Version)
96			}
97			if err := validateMutationDefinition(*existing, mutation); err != nil {
98				return false, err
99			}
100			result = applyCircuitMutation(existing, mutation)
101			return true, nil
102		})
103		return result, err
104	}
105	
106	// PartialCircuit carries optional replacement fields for one draft circuit
107	// version. A nil pointer leaves the stored field untouched; a non-nil pointer
108	// — even to zero or to the empty string — replaces the field. This lets a
109	// caller change exactly one field without restating the others.
110	type PartialCircuit struct {
111		Constraints   *int
112		PublicInputs  *int
113		PrivateInputs *int
114		Description   *string
115	}
116	
117	// UpdateCircuitPartial modifies selected fields of a draft circuit version.
118	//
119	// Only fields present in patch are changed; omitted fields keep their stored
120	// values. A non-nil pointer still replaces its field even when it points at
121	// zero or the empty string (explicit zero clears an input count, an empty
122	// string clears the description). The whole merged result is validated
123	// before anything is committed: constraints must stay positive and input
124	// counts non-negative, and when a constraint definition is already imported
125	// the merged counts must keep it legal (exact constraint count, every
126	// referenced wire inside the new input layout). Any rejected field refuses
127	// the entire change — description, counts and the stored definition all
128	// remain as they were. The merged result is checked through the same
129	// circuitMutation helpers as UpdateCircuit's whole replacement.
130	//
131	// Existence and frozen state are settled before the merged counts are
132	// judged: unknown versions yield ErrNotFound and frozen versions
133	// ErrFrozen, even when the patch carries an illegal count or no field at
134	// all. A patch that provides no modifiable field at all returns the stored
135	// record unchanged and commits nothing (no new version, no data write).
136	func (s *Store) UpdateCircuitPartial(name string, version int, patch PartialCircuit) (Circuit, error) {
137		if err := validateCircuitKey(name, version); err != nil {
138			return Circuit{}, err
139		}
140		hasField := patch.Constraints != nil || patch.PublicInputs != nil ||
141			patch.PrivateInputs != nil || patch.Description != nil
142	
143		var result Circuit
144		err := s.withLock(func() (bool, error) {
145			existing := findCircuit(s.data.Circuits, name, version)
146			if existing == nil {
147				return false, notFoundf("circuit %q version %d does not exist", name, version)
148			}
149			if existing.Frozen {
150				return false, frozenf("circuit %q version %d is frozen and cannot be modified", name, version)
151			}
152			// Merge the provided fields over the stored record; omitted fields
153			// keep their committed values, so the merged counts are always the
154			// complete result this modification would leave behind.
155			mutation := circuitMutation{
156				Constraints:   existing.Constraints,
157				PublicInputs:  existing.PublicInputs,
158				PrivateInputs: existing.PrivateInputs,
159				Description:   existing.Description,
160			}
161			if patch.Constraints != nil {
162				mutation.Constraints = *patch.Constraints
163			}
164			if patch.PublicInputs != nil {
165				mutation.PublicInputs = *patch.PublicInputs
166			}
167			if patch.PrivateInputs != nil {
168				mutation.PrivateInputs = *patch.PrivateInputs
169			}
170			if patch.Description != nil {
171				mutation.Description = *patch.Description
172			}
173			if err := validateMutationCounts(mutation); err != nil {
174				return false, err
175			}
176			if err := validateMutationDefinition(*existing, mutation); err != nil {
177				return false, err
178			}
179			// No modifiable field was provided: return the stored record without
180			// committing anything.
181			if !hasField {
182				result = circuitFromPersist(*existing)
183				return false, nil
184			}
185			result = applyCircuitMutation(existing, mutation)
186			return true, nil
187		})
188		return result, err
189	}
