191	// --- draft update internals -----------------------------------------------
192	//
193	// circuitMutation is the complete set of updatable draft fields one
194	// modification would leave committed: the three counts and the description.
195	// Both public update entry points resolve their request into this type —
196	// UpdateCircuit takes all four values from the request, UpdateCircuitPartial
197	// merges request fields over the stored record — and then share the same
198	// count rules, imported-definition compatibility check and commit, so the
199	// two usages can never drift apart. A mutation never replaces the stored
200	// constraint definition; it is only checked against it.
201	type circuitMutation struct {
202		Constraints   int
203		PublicInputs  int
204		PrivateInputs int
205		Description   string
206	}
207	
208	// validateMutationCounts holds the basic count rules for any draft update:
209	// constraints must be greater than zero and both input counts must not be
210	// negative. The rules are judged on the mutation's complete resulting
211	// counts, not on the supplied fields alone.
212	func validateMutationCounts(m circuitMutation) error {
213		return validateCounts(m.Constraints, m.PublicInputs, m.PrivateInputs)
214	}
215	
216	// validateMutationDefinition holds the rule shared with imported
217	// definitions: when the version already has one, the mutation's complete
218	// resulting counts must keep it legal — exactly as many constraints as the
219	// definition and every referenced wire inside the resulting public/private
220	// input layout. An unreadable stored definition is reported as data
221	// corruption. A version without a definition imposes no extra rule.
222	func validateMutationDefinition(existing persistCircuit, m circuitMutation) error {
223		if existing.Definition == nil {
224			return nil
225		}
226		parsed, perr := definitionFromPersist(*existing.Definition, existing.PublicInputs, existing.PrivateInputs)
227		if perr != nil {
228			return corruptf("stored definition for %q v%d is unreadable: %v", existing.Name, existing.Version, perr)
229		}
230		if !parsed.compatibleWith(m.Constraints, m.PublicInputs, m.PrivateInputs) {
231			return invalidf("update rejected: it would make the imported constraint definition illegal (constraint count or wire layout mismatch); the whole change is refused")
232		}
233		return nil
234	}
235	
236	// applyCircuitMutation commits a validated mutation onto the stored draft
237	// record, overwriting the three counts and the description together. The
238	// name, version, frozen flag and imported definition are never touched. The
239	// caller is responsible for all validation and for holding the store lock.
240	func applyCircuitMutation(existing *persistCircuit, m circuitMutation) Circuit {
241		existing.Constraints = m.Constraints
242		existing.PublicInputs = m.PublicInputs
243		existing.PrivateInputs = m.PrivateInputs
244		existing.Description = m.Description
245		return circuitFromPersist(*existing)
246	}
247	
248	// FreezeCircuit freezes a circuit version. Unknown versions yield
249	// ErrNotFound. Freezing an already-frozen version returns that version
250	// unchanged (idempotent). Once frozen, name, version and the three counts
251	// can never change again.
252	func (s *Store) FreezeCircuit(name string, version int) (Circuit, error) {
253		if err := validateCircuitKey(name, version); err != nil {
254			return Circuit{}, err
255		}
256	
257		var result Circuit
258		err := s.withLock(func() (bool, error) {
259			existing := findCircuit(s.data.Circuits, name, version)
260			if existing == nil {
261				return false, notFoundf("circuit %q version %d does not exist", name, version)
262			}
263			if existing.Frozen {
264				result = circuitFromPersist(*existing)
265				return false, nil
266			}
267			existing.Frozen = true
268			result = circuitFromPersist(*existing)
269			return true, nil
270		})
271		return result, err
272	}
273	
274	// CopyCircuit creates a new draft version of a circuit name by copying a
275	// frozen source version. The target version must be a positive integer
276	// different from the source version; it need not be consecutive or greater.
277	//
278	// The copy carries over the source's description, constraint count, public
279	// and private input counts, and — when the source has one — its complete
280	// constraint definition (modulus, constraint order and wire layout). A
281	// counts-only source produces a counts-only target with no definition. The
282	// new draft is fully independent: updating, re-importing or freezing it
283	// never touches the source, and the source's compiled artifacts, trusted
284	// setup and registered jobs are never copied or bound to the target. The
285	// target must register its own setup and compile its own artifact after
286	// freezing; the source's hash cannot satisfy the target's input checks or
287	// job bindings.
288	//
289	// Copying is idempotent: if the target already exists as a draft whose
290	// description, counts and definition are semantically equal to the source,
291	// the stored target is returned unchanged and nothing is written. A frozen
292	// target or a target whose description, counts or definition has changed
293	// yields ErrConflict. An unknown source yields ErrNotFound and an unfrozen
294	// source ErrNotFrozen; the source is always checked before the target.
295	func (s *Store) CopyCircuit(name string, version, toVersion int) (Circuit, error) {
296		if err := validateCircuitKey(name, version); err != nil {
297			return Circuit{}, err
298		}
299		if err := validateCircuitKey(name, toVersion); err != nil {
300			return Circuit{}, err
301		}
302		if version == toVersion {
303			return Circuit{}, invalidf("source and target version must differ for circuit %q", name)
304		}
305	
306		var result Circuit
307		err := s.withLock(func() (bool, error) {
308			source := findCircuit(s.data.Circuits, name, version)
309			if source == nil {
310				return false, notFoundf("circuit %q version %d does not exist", name, version)
311			}
312			if !source.Frozen {
313				return false, notFrozenf("circuit %q version %d must be frozen before it can be copied as a new draft", name, version)
314			}
315			target := findCircuit(s.data.Circuits, name, toVersion)
316			if target != nil {
317				if target.Frozen {
318					return false, conflictf("circuit %q version %d already exists and is frozen", name, toVersion)
319				}
320				if !circuitCopyMatches(*source, *target) {
321					return false, conflictf("circuit %q version %d already exists with content that differs from the source", name, toVersion)
322				}
323				result = circuitFromPersist(*target)
324				return false, nil
325			}
326			record := persistCircuit{
327				Name: name, Version: toVersion,
328				Constraints: source.Constraints, PublicInputs: source.PublicInputs, PrivateInputs: source.PrivateInputs,
329				Frozen: false, Description: source.Description,
330			}
331			if source.Definition != nil {
332				def := *source.Definition
333				record.Definition = &def
334			}
335			s.data.Circuits = append(s.data.Circuits, record)
336			result = circuitFromPersist(record)
337			return true, nil
338		})
339		return result, err
340	}
341	
342	// RecordSetup records a trusted setup for one frozen circuit version. The
343	// record belongs exclusively to that name+version. Unknown versions yield
344	// ErrNotFound; non-frozen versions yield ErrNotFrozen. Re-registering a
345	// setup for the same version is idempotent and adds no duplicate record.
346	func (s *Store) RecordSetup(name string, version int) (Setup, error) {
347		if err := validateCircuitKey(name, version); err != nil {
348			return Setup{}, err
349		}
350	
351		var result Setup
352		err := s.withLock(func() (bool, error) {
353			circuit := findCircuit(s.data.Circuits, name, version)
354			if circuit == nil {
355				return false, notFoundf("circuit %q version %d does not exist", name, version)
356			}
357			if !circuit.Frozen {
358				return false, notFrozenf("circuit %q version %d must be frozen before its trusted setup is recorded", name, version)
359			}
360			if existing := findSetup(s.data.Setups, name, version); existing != nil {
361				result = setupFromPersist(*existing)
362				return false, nil
363			}
364			record := persistSetup{Name: name, Version: version}
365			s.data.Setups = append(s.data.Setups, record)
366			result = setupFromPersist(record)
367			return true, nil
368		})
369		return result, err
370	}
