482	// ListCircuits returns all stored circuit versions ordered by circuit name
483	// (lexicographically) and then by ascending version number.
484	func (s *Store) ListCircuits() ([]Circuit, error) {
485		var result []Circuit
486		err := s.withLockRead(func() error {
487			ordered := append([]persistCircuit(nil), s.data.Circuits...)
488			sort.Slice(ordered, func(i, j int) bool {
489				if ordered[i].Name != ordered[j].Name {
490					return ordered[i].Name < ordered[j].Name
491				}
492				return ordered[i].Version < ordered[j].Version
493			})
494			result = make([]Circuit, len(ordered))
495			for i, c := range ordered {
496				result[i] = circuitFromPersist(c)
497			}
498			return nil
499		})
500		return result, err
501	}
