555	// --- validation helpers ---------------------------------------------------
556	
557	func validateCircuitKey(name string, version int) error {
558		if strings.TrimSpace(name) == "" {
559			return invalidf("circuit name must be non-empty and not only whitespace")
560		}
561		if version <= 0 {
562			return invalidf("circuit %q version must be a positive integer, got %d", name, version)
563		}
564		return nil
565	}
566	
567	// maxInputWires is the largest declared input count that stays representable
568	// on the running platform. Wire numbering always reserves wire 0 for the
569	// constant one, so the wires a version names are 0 plus its public and private
570	// inputs: the declared counts must satisfy 1 + public + private <= M, where M
571	// is the largest positive value the platform's int can hold. The check is done
572	// without ever adding the counts, so a layout whose sum would wrap (e.g.
573	// public=M with one private input) is refused rather than accepted through
574	// integer wraparound as a small, representable layout.
575	const maxInputWires = math.MaxInt
576	
577	// inputLayoutRepresentable reports whether the constant wire plus the public
578	// and private inputs fits inside the platform's int. Callers already guarantee
579	// both counts are non-negative.
580	func inputLayoutRepresentable(publicInputs, privateInputs int) bool {
581		return publicInputs <= maxInputWires-1 && privateInputs <= maxInputWires-1-publicInputs
582	}
583	
584	func validateCounts(constraints, publicInputs, privateInputs int) error {
585		if constraints <= 0 {
586			return invalidf("constraints must be greater than zero, got %d", constraints)
587		}
588		if publicInputs < 0 {
589			return invalidf("public input count must not be negative, got %d", publicInputs)
590		}
591		if privateInputs < 0 {
592			return invalidf("private input count must not be negative, got %d", privateInputs)
593		}
594		if !inputLayoutRepresentable(publicInputs, privateInputs) {
595			return invalidf("input layout is not representable: 1 constant wire + %d public + %d private inputs exceeds the platform limit of %d wires",
596				publicInputs, privateInputs, maxInputWires)
597		}
598		return nil
599	}
600	
601	// --- lookup / mapping helpers --------------------------------------------
602	
603	func findCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
604		for i := range cs {
605			if cs[i].Name == name && cs[i].Version == version {
606				return &cs[i]
607			}
608		}
609		return nil
610	}
611	
612	func findSetup(ps []persistSetup, name string, version int) *persistSetup {
613		for i := range ps {
614			if ps[i].Name == name && ps[i].Version == version {
615				return &ps[i]
616			}
617		}
618		return nil
619	}
620	
621	func findJob(js []persistJob, id string) *persistJob {
622		for i := range js {
623			if js[i].ID == id {
624				return &js[i]
625			}
626		}
627		return nil
628	}
629	
630	func sameJobRequest(stored persistJob, request Job) bool {
631		return stored.Circuit == request.Circuit &&
632			stored.Version == request.Version &&
633			stored.Kind == request.Kind &&
634			stored.Attempt == request.Attempt &&
635			stored.CompiledHash == request.CompiledHash
636	}
637	
638	func circuitFromPersist(c persistCircuit) Circuit {
639		return Circuit{
640			Name: c.Name, Version: c.Version,
641			Constraints: c.Constraints, PublicInputs: c.PublicInputs, PrivateInputs: c.PrivateInputs,
642			Frozen: c.Frozen, Description: c.Description,
643		}
644	}
645	
646	// circuitCopyMatches reports whether target is the same draft content that a
647	// copy of source would create: same description, same three counts and a
648	// semantically equal constraint definition. Definition equality follows the
649	// existing normalization semantics (terms merged per wire, coefficients
650	// reduced modulo p, zeros dropped, wires sorted ascending); a missing
651	// definition differs from a present one.
652	func circuitCopyMatches(source, target persistCircuit) bool {
653		if source.Description != target.Description {
654			return false
655		}
656		if source.Constraints != target.Constraints ||
657			source.PublicInputs != target.PublicInputs ||
658			source.PrivateInputs != target.PrivateInputs {
659			return false
660		}
661		return definitionsEqual(source.Definition, target.Definition, source.PublicInputs, source.PrivateInputs)
662	}
663	
664	// definitionsEqual compares two stored definitions for semantic equality.
665	// Both nil is equal; one nil and the other not is different. When both are
666	// present they are parsed through the existing normalization pipeline and
667	// compared by modulus, constraint count and each side's wire/coefficient
668	// pairs. The public/private layout is the source's; the caller has already
669	// confirmed the counts match.
670	func definitionsEqual(d1, d2 *persistDefinition, public, private int) bool {
671		if d1 == nil && d2 == nil {
672			return true
673		}
674		if d1 == nil || d2 == nil {
675			return false
676		}
677		p1, err := definitionFromPersist(*d1, public, private)
678		if err != nil {
679			return false
680		}
681		p2, err := definitionFromPersist(*d2, public, private)
682		if err != nil {
683			return false
684		}
685		if p1.modulus != p2.modulus || len(p1.constraints) != len(p2.constraints) {
686			return false
687		}
688		for i := range p1.constraints {
689			if !canonicalTermsEqual(p1.constraints[i].a, p2.constraints[i].a) ||
690				!canonicalTermsEqual(p1.constraints[i].b, p2.constraints[i].b) ||
691				!canonicalTermsEqual(p1.constraints[i].c, p2.constraints[i].c) {
692				return false
693			}
694		}
695		return true
696	}
697	
698	// canonicalTermsEqual reports whether two normalized term slices are
699	// identical wire-by-wire and coefficient-by-coefficient.
700	func canonicalTermsEqual(t1, t2 []parsedTerm) bool {
701		if len(t1) != len(t2) {
702			return false
703		}
704		for i := range t1 {
705			if t1[i].wire != t2[i].wire || t1[i].value != t2[i].value {
706				return false
707			}
708		}
709		return true
710	}
711	
712	func setupFromPersist(p persistSetup) Setup {
713		return Setup{Name: p.Name, Version: p.Version}
714	}
715	
716	func jobFromPersist(j persistJob) Job {
717		return Job{
718			ID: j.ID, Circuit: j.Circuit, Version: j.Version,
719			Kind: j.Kind, Attempt: j.Attempt, Artifact: j.Artifact,
720			CompiledHash: j.CompiledHash,
721		}
722	}
723

