284		for i := range as {
285			if as[i].Name == name && as[i].Version == version {
286				return &as[i]
287			}
288		}
289		return nil
290	}
291	
292	func artifactFromPersist(a persistArtifact) Artifact {
293		return Artifact{
294			Name: a.Name, Version: a.Version,
295			Modulus: int(a.Modulus), Constraints: a.Constraints, Hash: a.Hash,
296		}
297	}
298	
299	func definitionMissingf(format string, args ...any) error {
300		return StoreError{Kind: ErrDefinitionMissing.Kind, Detail: fmt.Sprintf(format, args...)}
301	}
302	
303	func artifactMissingf(format string, args ...any) error {
304		return StoreError{Kind: ErrArtifactMissing.Kind, Detail: fmt.Sprintf(format, args...)}
305	}
306	
307	func artifactMismatchf(format string, args ...any) error {
308		return StoreError{Kind: ErrArtifactMismatch.Kind, Detail: fmt.Sprintf(format, args...)}
309	}
