132	func TestArtifactHashInvariance(t *testing.T) {
133		base := `{"modulus":"7","constraints":[
134			{"a":[{"wire":1,"coeff":"1"}],"b":[{"wire":2,"coeff":"2"},{"wire":0,"coeff":"0"}],"c":[{"wire":0,"coeff":"3"}]}]}`
135		want := hashOfDoc(t, base, "c", 1, 1, 1, 1)
136	
137		variants := []string{
138			// JSON whitespace only.
