140				"{ \"a\" : [ {\"wire\":1,\"coeff\":\"1\"} ], \"b\" : [ {\"wire\":2,\"coeff\":\"2\"} ], \"c\" : [ {\"wire\":0,\"coeff\":\"3\"} ] } ] }",
141			// Term order within a side.
142			`{"modulus":"7","constraints":[
143				{"a":[{"wire":1,"coeff":"1"}],"b":[{"wire":0,"coeff":"0"},{"wire":2,"coeff":"2"}],"c":[{"wire":0,"coeff":"3"}]}]}`,
144			// Duplicate terms that merge.
