149				{"a":[{"wire":1,"coeff":"1"},{"wire":2,"coeff":"0"}],"b":[{"wire":2,"coeff":"2"}],"c":[{"wire":0,"coeff":"3"}]}]}`,
150			// Coefficients differing by a multiple of the modulus (7, 14, -7).
151			`{"modulus":"7","constraints":[
