154			`{"modulus":"7","constraints":[
155				{"a":[{"wire":1,"coeff":"7000000000000000000000001"}],"b":[{"wire":2,"coeff":"2"}],"c":[{"wire":0,"coeff":"3"}]}]}`,
156		}
