342	func TestCheckInputVerdictsAndGating(t *testing.T) {
343		s := openTestStore(t)
344		// One satisfying constraint 1*2 = 6 mod 7? use pub*priv = c:
345		// wire1 * wire2 = 6, satisfied by (2,3) and (6,1).
346		seedDraftWithDef(t, s, "c", 1, 1, 1, validDef)
347		if _, err := s.FreezeCircuit("c", 1); err != nil {
348			t.Fatal(err)
349		}
350		artifact, err := s.CompileCircuit("c", 1)
351		if err != nil {
352			t.Fatal(err)
353		}
354	
355		ok := Witness{Public: []string{"2"}, Private: []string{"3"}}
356		res, err := s.CheckInput("c", 1, artifact.Hash, ok)
357		if err != nil || !res.Satisfied || res.FirstFailure != 0 || res.Hash != artifact.Hash {
358			t.Fatalf("satisfied check: %+v %v", res, err)
359		}
360		// Negative and arbitrary-length values interpreted mod p.
361		// -5 ≡ 2 and -4 ≡ 3 mod 7, product 20 ≡ 6.
362		okNeg := Witness{Public: []string{"-5"}, Private: []string{"-4"}}
363		res, err = s.CheckInput("c", 1, artifact.Hash, okNeg)
364		if err != nil || !res.Satisfied {
365			t.Fatalf("negative witness mod p should satisfy: %+v %v", res, err)
366		}
367		// (2 + 7·10^24) · 3 ≡ 6: huge coefficients reduce before evaluation.
368		okBig := Witness{Public: []string{"7000000000000000000000002"}, Private: []string{"3"}}
369		res, err = s.CheckInput("c", 1, artifact.Hash, okBig)
370		if err != nil || !res.Satisfied {
371			t.Fatalf("huge witness mod p should satisfy: %+v %v", res, err)
372		}
373	
374		bad := Witness{Public: []string{"2"}, Private: []string{"4"}} // 2*4=1 != 6
375		res, err = s.CheckInput("c", 1, artifact.Hash, bad)
376		if err != nil {
377			t.Fatal(err)
378		}
379		if res.Satisfied || res.FirstFailure != 1 {
380			t.Fatalf("want unsatisfied first_failure=1, got %+v", res)
381		}
382	
383		// First failing constraint is reported 1-based.
384		two := `{"modulus":"7","constraints":[
385			{"a":[{"wire":1,"coeff":"1"}],"b":[{"wire":2,"coeff":"1"}],"c":[{"wire":0,"coeff":"6"}]},
386			{"a":[{"wire":1,"coeff":"1"}],"b":[{"wire":2,"coeff":"1"}],"c":[{"wire":0,"coeff":"0"}]}]}`
387		if _, err := s.CreateCircuit(Circuit{Name: "c", Version: 3, Constraints: 2,
388			PublicInputs: 1, PrivateInputs: 1, Description: "two"}); err != nil {
389			t.Fatal(err)
390		}
391		if _, err := s.ImportConstraints("c", 3, writeTempJSON(t, two)); err != nil {
392			t.Fatal(err)
393		}
394		s.FreezeCircuit("c", 3)
395		a3, _ := s.CompileCircuit("c", 3)
396		res, err = s.CheckInput("c", 3, a3.Hash, Witness{Public: []string{"2"}, Private: []string{"3"}})
397		if err != nil || res.Satisfied || res.FirstFailure != 2 {
398			t.Fatalf("want first_failure=2, got %+v %v", res, err)
399		}
400	
401		// Gating failures.
402		if _, err := s.CheckInput("ghost", 1, artifact.Hash, ok); !errors.Is(err, ErrNotFound) {
403			t.Fatalf("unknown version: %v", err)
404		}
405		if _, err := s.CreateCircuit(Circuit{Name: "d", Version: 1, Constraints: 1, Description: "d"}); err != nil {
406			t.Fatal(err)
407		}
408		if _, err := s.CheckInput("d", 1, artifact.Hash, ok); !errors.Is(err, ErrNotFrozen) {
409			t.Fatalf("unfrozen: %v", err)
410		}
411		// Frozen but never compiled -> missing artifact.
412		s.FreezeCircuit("d", 1)
413		if _, err := s.CheckInput("d", 1, artifact.Hash, ok); !errors.Is(err, ErrArtifactMissing) {
414			t.Fatalf("missing artifact: %v", err)
415		}
416		// Foreign/wrong hash -> mismatch.
417		if _, err := s.CheckInput("c", 1, artifact.Hash+"00", ok); !errors.Is(err, ErrArtifactMismatch) {
418			t.Fatalf("wrong hash: %v", err)
419		}
420		// Input-format failures never evaluate.
421		for _, w := range []Witness{
422			{Public: []string{}, Private: []string{"3"}},
423			{Public: []string{"2", "x"}, Private: []string{"3"}},
424			{Public: []string{"2"}, Private: []string{"xx"}},
425			{Public: []string{"2"}, Private: []string{}},
426		} {
427			if _, err := s.CheckInput("c", 1, artifact.Hash, w); !errors.Is(err, ErrInvalidInput) {
428				t.Fatalf("want input format error for %+v, got %v", w, err)
429			}
430		}
431	}
