530	// malformed file never masks a failed binding: business errors are reported
531	// before the file's contents are parsed.
532	func TestCheckInputFileGatingPrecedence(t *testing.T) {
533		s := openTestStore(t)
534		seedDraftWithDef(t, s, "c", 1, 1, 1, validDef)
