565		// never rewrites it as another cause.
566		if _, err := s.CheckInputFile("c", 1, a.Hash, filepath.Join(t.TempDir(), "missing.json")); !errors.Is(err, ErrInvalidInput) {
567			t.Fatalf("unreadable file must be an input format error, got %v", err)
