605	// A tampered stored definition or an artifact inconsistent with its
606	// definition is refused on open like any other read failure.
607	func TestTamperedDefinitionAndArtifactRefused(t *testing.T) {
608		dir := filepath.Join(t.TempDir(), "bench")
609		s, _ := Open(dir)
610		seedDraftWithDef(t, s, "c", 1, 1, 1, validDef)
611		s.FreezeCircuit("c", 1)
612		if _, err := s.CompileCircuit("c", 1); err != nil {
613			t.Fatal(err)
614		}
615		s.Close()
616		dataFile := filepath.Join(dir, dirDataFile)
617	
618		tamper := func(t *testing.T, mutate func([]byte) []byte) {
619			t.Helper()
620			original, err := os.ReadFile(dataFile)
621			if err != nil {
622				t.Fatal(err)
623			}
624			bad := mutate(append([]byte(nil), original...))
625			if err := os.WriteFile(dataFile, bad, 0o644); err != nil {
626				t.Fatal(err)
627			}
628			if _, err := Open(dir); !errors.Is(err, ErrDataCorrupt) {
629				t.Fatalf("want data corrupt, got %v", err)
630			}
631			// File must be left untouched on refusal.
632			left, _ := os.ReadFile(dataFile)
633			if string(left) != string(bad) {
634				t.Fatal("damaged file was overwritten on refusal")
635			}
636			if err := os.WriteFile(dataFile, original, 0o644); err != nil {
637				t.Fatal(err)
638			}
639		}
640	
641		t.Run("artifact hash", func(t *testing.T) {
642			tamper(t, func(b []byte) []byte {
643				return replaceFirst(b, []byte(`"hash": "`), []byte(`"hash": "deadbeef`))
644			})
645		})
646		t.Run("definition modulus", func(t *testing.T) {
647			tamper(t, func(b []byte) []byte {
648				return replaceFirst(b, []byte(`"modulus": "7"`), []byte(`"modulus": "11"`))
649			})
650		})
651		t.Run("definition coeff", func(t *testing.T) {
652			tamper(t, func(b []byte) []byte {
653				return replaceFirst(b, []byte(`"coeff": "6"`), []byte(`"coeff": "5"`))
654			})
655		})
656		t.Run("artifact count", func(t *testing.T) {
657			tamper(t, func(b []byte) []byte {
658				return replaceFirst(b, []byte(`"constraints": 1,`), []byte(`"constraints": 2,`))
659			})
660		})
661	
662		// After restoring, the directory reads cleanly.
663		if _, err := Open(dir); err != nil {
664			t.Fatalf("restored dir should open: %v", err)
665		}
666	}
