765	func TestParseWitness(t *testing.T) {
766		cases := []struct {
767			name      string
768			doc       string
769			pub, priv int
770			ok        bool
771		}{
772			{"good", `{"public":["1","-2"],"private":["999999999999999999999999"]}`, 2, 1, true},
773			{"empty arrays", `{"public":[],"private":[]}`, 0, 0, true},
774			{"missing public", `{"private":[]}`, 0, 0, false},
