package zkcircuit

import "fmt"

// Failure kinds reported by the persistent workbench. Callers can inspect a
// returned error with errors.Is to distinguish rule violations; human-facing
// clients may also use the messages directly.
var (
	// ErrInvalidArgument is a malformed request (empty name, bad counts, …).
	ErrInvalidArgument = StoreError{Kind: "invalid argument"}
	// ErrNotFound means the referenced circuit version does not exist.
	ErrNotFound = StoreError{Kind: "not found"}
	// ErrConflict means an existing record disagrees with the request.
	ErrConflict = StoreError{Kind: "conflict"}
	// ErrDraftRequired means an operation requires a draft circuit version.
	ErrDraftRequired = StoreError{Kind: "draft required"}
	// ErrFrozen means the circuit version is frozen and cannot be modified.
	ErrFrozen = StoreError{Kind: "frozen"}
	// ErrNotFrozen means trusted setup or a job requires a frozen version.
	ErrNotFrozen = StoreError{Kind: "not frozen"}
	// ErrSetupMissing means the frozen version has no recorded trusted setup.
	ErrSetupMissing = StoreError{Kind: "trusted setup missing"}
	// ErrUnsupportedKind means a job kind other than prove was submitted.
	ErrUnsupportedKind = StoreError{Kind: "unsupported job kind"}
	// ErrDefinitionMissing means a frozen version has registered counts but no
	// imported constraint definition, so it cannot be compiled.
	ErrDefinitionMissing = StoreError{Kind: "constraint definition missing"}
	// ErrArtifactMissing means the version has no compiled artifact.
	ErrArtifactMissing = StoreError{Kind: "compiled artifact missing"}
	// ErrArtifactMismatch means the supplied hash does not belong to the
	// target version's compiled artifact.
	ErrArtifactMismatch = StoreError{Kind: "artifact mismatch"}
	// ErrInvalidInput means a witness document is malformed or does not match
	// the version's declared input layout.
	ErrInvalidInput = StoreError{Kind: "input format error"}
	// ErrDataCorrupt means the on-disk data file cannot be read safely.
	ErrDataCorrupt = StoreError{Kind: "data corrupt"}
)

// StoreError is a domain error with a human-readable Detail tagged with a
// stable Kind. The zero value is not used; construct via the helpers below.
type StoreError struct {
	Kind   string
	Detail string
}

func (e StoreError) Error() string {
	if e.Detail == "" {
		return e.Kind
	}
	return e.Kind + ": " + e.Detail
}

// Is supports errors.Is on Kind while ignoring Detail.
func (e StoreError) Is(target error) bool {
	other, ok := target.(StoreError)
	return ok && other.Kind == e.Kind
}

func invalidf(format string, args ...any) error {
	return StoreError{Kind: ErrInvalidArgument.Kind, Detail: fmt.Sprintf(format, args...)}
}

func notFoundf(format string, args ...any) error {
	return StoreError{Kind: ErrNotFound.Kind, Detail: fmt.Sprintf(format, args...)}
}

func conflictf(format string, args ...any) error {
	return StoreError{Kind: ErrConflict.Kind, Detail: fmt.Sprintf(format, args...)}
}

func draftRequiredf(format string, args ...any) error {
	return StoreError{Kind: ErrDraftRequired.Kind, Detail: fmt.Sprintf(format, args...)}
}

func frozenf(format string, args ...any) error {
	return StoreError{Kind: ErrFrozen.Kind, Detail: fmt.Sprintf(format, args...)}
}

func notFrozenf(format string, args ...any) error {
	return StoreError{Kind: ErrNotFrozen.Kind, Detail: fmt.Sprintf(format, args...)}
}

func setupMissingf(format string, args ...any) error {
	return StoreError{Kind: ErrSetupMissing.Kind, Detail: fmt.Sprintf(format, args...)}
}

func corruptf(format string, args ...any) error {
	return StoreError{Kind: ErrDataCorrupt.Kind, Detail: fmt.Sprintf(format, args...)}
}

func inputFormatf(format string, args ...any) error {
	return StoreError{Kind: ErrInvalidInput.Kind, Detail: fmt.Sprintf(format, args...)}
}

package zkcircuit

import (
	"math/big"
	"testing"
)

// This file is an arithmetic regression guard for input checking. The
// pre-existing max-modulus test only multiplied two small single-term values;
// these cases exercise multi-term linear combinations (constant wire 0, public
// and private inputs together) at the largest legal prime 2147483647, where
// coefficients and inputs sit close to the modulus and the unreduced products
// and linear-combination sums exceed the int32 range. They also pin down the
// "first failing constraint only" semantics and the meaning of repeated wires
// and cancelling coefficients.

const regressionMaxPrime = "2147483647"

// regressionCircuit creates a draft with count declared constraints, imports
// def, freezes and compiles it, returning the store and the compiled
// artifact. Every check is then bound to the artifact's own hash, the only
// public way a check can run.
func regressionCircuit(t *testing.T, name string, version, pub, priv, count int, def string) (*Store, Artifact) {
	t.Helper()
	s := openTestStore(t)
	if _, err := s.CreateCircuit(Circuit{Name: name, Version: version, Constraints: count,
		PublicInputs: pub, PrivateInputs: priv, Description: name}); err != nil {
		t.Fatal(err)
	}
	if _, err := s.ImportConstraints(name, version, writeTempJSON(t, def)); err != nil {
		t.Fatalf("import: %v", err)
	}
	if _, err := s.FreezeCircuit(name, version); err != nil {
		t.Fatal(err)
	}
	artifact, err := s.CompileCircuit(name, version)
	if err != nil {
		t.Fatalf("compile: %v", err)
	}
	return s, artifact
}

// assertSatisfied and assertUnsatisfied pin the complete verdict contract:
// a check that completes (satisfiable or not) is never a call failure, the
// verdict carries only the conclusion, the bound hash (echoing the request)
// and the 1-based first-failure index.
func assertSatisfied(t *testing.T, s *Store, name string, version int, hash string, w Witness) {
	t.Helper()
	res, err := s.CheckInput(name, version, hash, w)
	if err != nil {
		t.Fatalf("satisfying check returned a call error: %v", err)
	}
	if !res.Satisfied || res.FirstFailure != 0 {
		t.Fatalf("want satisfied with first_failure=0, got %+v", res)
	}
	if res.Hash != hash {
		t.Fatalf("bound hash %q does not match request %q", res.Hash, hash)
	}
}

func assertUnsatisfied(t *testing.T, s *Store, name string, version int, hash string, w Witness, wantFailure int) {
	t.Helper()
	res, err := s.CheckInput(name, version, hash, w)
	if err != nil {
		t.Fatalf("an unsatisfied constraint is a completed check, not a call error: %v", err)
	}
	if res.Satisfied {
		t.Fatalf("want unsatisfied, got %+v", res)
	}
	if res.FirstFailure != wantFailure {
		t.Fatalf("want first_failure=%d, got %+v", wantFailure, res)
	}
	if res.Hash != hash {
		t.Fatalf("bound hash %q does not match request %q", res.Hash, hash)
	}
}

// TestMaxPrimeMultiTermNoOverflow is the central regression the old coverage
// could not catch. The single constraint mixes wire 0 (constant 1), a public
// input and a private input on every side, with coefficients and input values
// all close to p = 2147483647:
//
//	a = (p-15)·1 + (p-2)·x
//	b = (p-28)·1 + (p-4)·y
//	c = (p-63)·1 + (p-7)·x + (p-8)·y
//
// For x = p-5, y = p-6 the reduced values are a = p-5, b = p-4 and
// a·b ≡ 20 ≡ c (mod p). Both the reduced product (p-5)·(p-4) and the
// individual term products (p-2)·(p-5), (p-4)·(p-6) are ~4.61·10^18, above
// the int32 maximum: an evaluator that used 32-bit arithmetic at any step —
// accumulating a side or multiplying the two reduced combinations — would
// draw the wrong conclusion here.
func TestMaxPrimeMultiTermNoOverflow(t *testing.T) {
	def := `{"modulus":"` + regressionMaxPrime + `","constraints":[
		{"a":[{"wire":0,"coeff":"2147483632"},{"wire":1,"coeff":"2147483645"}],
		 "b":[{"wire":0,"coeff":"2147483619"},{"wire":2,"coeff":"2147483643"}],
		 "c":[{"wire":0,"coeff":"2147483584"},{"wire":1,"coeff":"2147483640"},{"wire":2,"coeff":"2147483639"}]}]}`
	s, artifact := regressionCircuit(t, "big", 1, 1, 1, 1, def)

	// Guard the premise of the test: the reduced combination product and the
	// intermediate term sums really do exceed int32, so any 32-bit-overflow
	// step is exposed.
	termProduct := new(big.Int).Mul(big.NewInt(2147483645), big.NewInt(2147483642))    // (p-2)(p-5)
	linearSum := new(big.Int).Add(big.NewInt(2147483632), termProduct)                 // (p-15)+(p-2)(p-5)
	residueProduct := new(big.Int).Mul(big.NewInt(2147483642), big.NewInt(2147483643)) // (p-5)(p-4)
	int32Max := big.NewInt(2147483647)
	if termProduct.Cmp(int32Max) <= 0 || linearSum.Cmp(int32Max) <= 0 || residueProduct.Cmp(int32Max) <= 0 {
		t.Fatalf("test premise lost: products/sums must exceed int32, got term=%s linear=%s residue=%s",
			termProduct, linearSum, residueProduct)
	}
	// And they stay inside int64, which is the implementation's own
	// exactness guarantee: this case is decided by modular reduction, not by
	// big-int fallback masking a narrower type.
	int64Max, _ := new(big.Int).SetString("9223372036854775807", 10)
	if termProduct.Cmp(int64Max) > 0 || linearSum.Cmp(int64Max) > 0 || residueProduct.Cmp(int64Max) > 0 {
		t.Fatalf("test values leave the int64 range the evaluator relies on")
	}

	good := Witness{Public: []string{"2147483642"}, Private: []string{"2147483641"}} // x=p-5, y=p-6
	assertSatisfied(t, s, "big", 1, artifact.Hash, good)

	// Same reduced assignment expressed with a negative private value
	// (-6 ≡ p-6 mod p): the decimal-string rules interpret it modulo p.
	neg := Witness{Public: []string{"2147483642"}, Private: []string{"-6"}}
	assertSatisfied(t, s, "big", 1, artifact.Hash, neg)

	// Changing the private input breaks the equation: y = p-7 makes a·b ≡ 0
	// while c ≡ 28 mod p. This must read unsatisfied, never "satisfied by
	// overflow".
	badPriv := Witness{Public: []string{"2147483642"}, Private: []string{"2147483640"}}
	assertUnsatisfied(t, s, "big", 1, artifact.Hash, badPriv, 1)

	// Changing the public input instead must likewise fail (a·b ≡ 12 ≠ 27).
	badPub := Witness{Public: []string{"2147483641"}, Private: []string{"2147483641"}}
	assertUnsatisfied(t, s, "big", 1, artifact.Hash, badPub, 1)

	// The satisfying witness genuinely depends on all three wire kinds
	// rather than on vacuous sides: zeroing both inputs gives
	// (p-15)·(p-28) ≡ 420 ≠ p-63, so it must not satisfy.
	zero := Witness{Public: []string{"0"}, Private: []string{"0"}}
	assertUnsatisfied(t, s, "big", 1, artifact.Hash, zero, 1)
}

// TestMaxPrimeFirstFailureOrdering pins the meaning of "only the first
// failing constraint is reported". One frozen version carries three
// constraints in definition order; witnesses are chosen so that the verdict
// points at the constraint that actually fails first:
//
//	wires: w1,w2 public = 5,4 ; w3,w4,w5 private = 7,2,29
//	C1: ((p-1) + 2·w1)·(1 + 3·w3) = 198
//	C2: (1 + 2·w2)·((p-1) + 3·w4) = 45
//	C3: (1 + w5)·1 = 30
//
// Every side is a genuine multi-term linear combination (constant + inputs),
// and the products run into the 10^18 range at p = 2147483647.
func TestMaxPrimeFirstFailureOrdering(t *testing.T) {
	def := `{"modulus":"` + regressionMaxPrime + `","constraints":[
		{"a":[{"wire":0,"coeff":"-1"},{"wire":1,"coeff":"2"}],
		 "b":[{"wire":0,"coeff":"1"},{"wire":3,"coeff":"3"}],
		 "c":[{"wire":0,"coeff":"198"}]},
		{"a":[{"wire":0,"coeff":"1"},{"wire":2,"coeff":"2"}],
		 "b":[{"wire":0,"coeff":"-1"},{"wire":4,"coeff":"3"}],
		 "c":[{"wire":0,"coeff":"45"}]},
		{"a":[{"wire":0,"coeff":"1"},{"wire":5,"coeff":"1"}],
		 "b":[{"wire":0,"coeff":"1"}],
		 "c":[{"wire":0,"coeff":"30"}]}]}`
	s, artifact := regressionCircuit(t, "ord", 1, 2, 3, 3, def)

	// Baseline: everything holds; first_failure is 0.
	base := Witness{Public: []string{"5", "4"}, Private: []string{"7", "2", "29"}}
	assertSatisfied(t, s, "ord", 1, artifact.Hash, base)

	// Earlier constraints hold, a later one fails: the result points at the
	// later constraint's real position.
	onlyC3 := Witness{Public: []string{"5", "4"}, Private: []string{"7", "2", "100"}}
	assertUnsatisfied(t, s, "ord", 1, artifact.Hash, onlyC3, 3)

	onlyC2 := Witness{Public: []string{"5", "4"}, Private: []string{"7", "8", "29"}}
	assertUnsatisfied(t, s, "ord", 1, artifact.Hash, onlyC2, 2)

	// Several constraints fail at once (here C2 and C3, C1 still holds): the
	// earliest failing one wins.
	c2AndC3 := Witness{Public: []string{"5", "10"}, Private: []string{"7", "2", "100"}}
	assertUnsatisfied(t, s, "ord", 1, artifact.Hash, c2AndC3, 2)

	// The first constraint failing must hide every later failure.
	c1First := Witness{Public: []string{"6", "10"}, Private: []string{"7", "2", "29"}}
	assertUnsatisfied(t, s, "ord", 1, artifact.Hash, c1First, 1)
}

// TestMaxPrimeCongruentRepresentationsAgree checks that, against one frozen
// definition, replacing inputs with other legal decimal representations that
// differ by an integer multiple of the modulus leaves both the satisfaction
// state and the first-failure position unchanged. The alternatives are
// negative and far longer than machine integers.
func TestMaxPrimeCongruentRepresentationsAgree(t *testing.T) {
	// Same three-constraint circuit as the ordering test, so the
	// first-failure index is meaningful in the unsatisfying family too.
	def := `{"modulus":"` + regressionMaxPrime + `","constraints":[
		{"a":[{"wire":0,"coeff":"-1"},{"wire":1,"coeff":"2"}],
		 "b":[{"wire":0,"coeff":"1"},{"wire":3,"coeff":"3"}],
		 "c":[{"wire":0,"coeff":"198"}]},
		{"a":[{"wire":0,"coeff":"1"},{"wire":2,"coeff":"2"}],
		 "b":[{"wire":0,"coeff":"-1"},{"wire":4,"coeff":"3"}],
		 "c":[{"wire":0,"coeff":"45"}]},
		{"a":[{"wire":0,"coeff":"1"},{"wire":5,"coeff":"1"}],
		 "b":[{"wire":0,"coeff":"1"}],
		 "c":[{"wire":0,"coeff":"30"}]}]}`
	s, artifact := regressionCircuit(t, "cong", 1, 2, 3, 3, def)
	p := big.NewInt(2147483647)
	pow10 := func(n int64) *big.Int {
		return new(big.Int).Exp(big.NewInt(10), big.NewInt(n), nil)
	}

	// Satisfying family: (w1,w2,w3,w4,w5) = (5,4,7,2,29). Each entry below is
	// congruent to the corresponding base value modulo p; the rewrites mix
	// huge positives and huge negatives.
	satisfying := []Witness{
		{Public: []string{"5", "4"}, Private: []string{"7", "2", "29"}},
		{
			Public: []string{
				new(big.Int).Add(big.NewInt(5), new(big.Int).Mul(pow10(20), p)).String(),
				new(big.Int).Sub(big.NewInt(4), new(big.Int).Mul(pow10(12), p)).String(),
			},
			Private: []string{
				new(big.Int).Add(big.NewInt(7), p).String(),
				new(big.Int).Sub(big.NewInt(2), new(big.Int).Add(p, p)).String(),
				new(big.Int).Add(big.NewInt(29), new(big.Int).Mul(pow10(8), p)).String(),
			},
		},
	}
	for i, w := range satisfying {
		res, err := s.CheckInput("cong", 1, artifact.Hash, w)
		if err != nil {
			t.Fatalf("satisfying case %d: %v", i, err)
		}
		if !res.Satisfied || res.FirstFailure != 0 || res.Hash != artifact.Hash {
			t.Fatalf("congruent satisfying case %d changed the verdict: %+v", i, res)
		}
	}

	// Unsatisfying family: base (5,4,7,8,29) fails first at C2. Congruent
	// rewrites (a 40-digit positive, two huge negatives) must keep the exact
	// same unsatisfied state and first-failure position.
	unsatisfying := []Witness{
		{Public: []string{"5", "4"}, Private: []string{"7", "8", "29"}},
		{
			Public: []string{
				new(big.Int).Sub(big.NewInt(5), new(big.Int).Mul(pow10(10), p)).String(),
				"4",
			},
			Private: []string{
				"7",
				new(big.Int).Add(big.NewInt(8), new(big.Int).Mul(pow10(30), p)).String(),
				new(big.Int).Sub(big.NewInt(29), p).String(),
			},
		},
	}
	for i, w := range unsatisfying {
		res, err := s.CheckInput("cong", 1, artifact.Hash, w)
		if err != nil {
			t.Fatalf("unsatisfying case %d returned a call error: %v", i, err)
		}
		if res.Satisfied || res.FirstFailure != 2 || res.Hash != artifact.Hash {
			t.Fatalf("congruent unsatisfying case %d changed the verdict: %+v", i, res)
		}
	}
}

// TestRepeatedWiresAndCancellingCoefficients checks that duplicate wire
// references are really summed (merged) and that coefficients that cancel to
// zero behave as the zero linear combination — including the discriminating
// case where one side cancels to zero but the other side still makes the
// equation false. Modulus 11 keeps the modular bookkeeping transparent.
//
// Wires: w1 public, w2 private. Four constraints in definition order:
//
//	C1: w1·w1 = 4                         (9·9 = 81 ≡ 4; fails for w1=3)
//	C2: (3·w1 + 8·w1)·1 = 5·w1 + 6·w1     -> 0 = 0 for every w1
//	C3: (2·w1 + 3·w1 + 6·w1)·w2 = 5·w2 + 6·w2 -> 0 = 0 for every w1,w2
//	C4: (5·w2 - 5·w2)·w1 = w2             -> left cancels; holds iff w2 = 0
func TestRepeatedWiresAndCancellingCoefficients(t *testing.T) {
	def := `{"modulus":"11","constraints":[
		{"a":[{"wire":1,"coeff":"1"}],"b":[{"wire":1,"coeff":"1"}],"c":[{"wire":0,"coeff":"4"}]},
		{"a":[{"wire":1,"coeff":"3"},{"wire":1,"coeff":"8"}],"b":[{"wire":0,"coeff":"1"}],"c":[{"wire":1,"coeff":"5"},{"wire":1,"coeff":"6"}]},
		{"a":[{"wire":1,"coeff":"2"},{"wire":1,"coeff":"3"},{"wire":1,"coeff":"6"}],"b":[{"wire":2,"coeff":"1"}],"c":[{"wire":2,"coeff":"5"},{"wire":2,"coeff":"6"}]},
		{"a":[{"wire":2,"coeff":"5"},{"wire":2,"coeff":"-5"}],"b":[{"wire":1,"coeff":"1"}],"c":[{"wire":2,"coeff":"1"}]}]}`
	s, artifact := regressionCircuit(t, "dup", 1, 1, 1, 4, def)

	// Satisfying: w1 = 9 (nonzero, so the cancellations do real work),
	// w2 = 0. C1 holds (81 ≡ 4), C2/C3 are 0 = 0, C4 is 0 = 0.
	good := Witness{Public: []string{"9"}, Private: []string{"0"}}
	assertSatisfied(t, s, "dup", 1, artifact.Hash, good)

	// The cancellation discriminator: w1 = 9 keeps C1-C3 holding, but C4's
	// left side cancels to zero by construction while its right side is 4:
	// the equation is false and must be recognised as such — a side that
	// merged to zero is not a wildcard. The verdict points at C4, proving
	// C1-C3 genuinely held rather than every constraint being skipped.
	discriminator := Witness{Public: []string{"9"}, Private: []string{"4"}}
	assertUnsatisfied(t, s, "dup", 1, artifact.Hash, discriminator, 4)

	// A failing first constraint hides the also-failing C4: w1 = 3 gives
	// 3·3 = 9 ≠ 4, so the first reported failure is 1.
	firstWins := Witness{Public: []string{"3"}, Private: []string{"4"}}
	assertUnsatisfied(t, s, "dup", 1, artifact.Hash, firstWins, 1)

	// Congruent representations of the satisfying witness: -2 ≡ 9 mod 11
	// and 11·10^18 ≡ 0; the verdict must stay satisfied/first_failure=0.
	congruentGood := Witness{Public: []string{"-2"}, Private: []string{"11000000000000000000"}}
	assertSatisfied(t, s, "dup", 1, artifact.Hash, congruentGood)
	// And 4 + 11·10^20 ≡ 4 must still fail at the cancellation constraint.
	congruentBad := Witness{
		Public:  []string{"-2"},
		Private: []string{new(big.Int).Add(big.NewInt(4), new(big.Int).Mul(big.NewInt(11), bigPow10(20))).String()},
	}
	assertUnsatisfied(t, s, "dup", 1, artifact.Hash, congruentBad, 4)

	// Inspect the merged canonical form behind the frozen version: the
	// coefficients on C2 side a (3 and 8 on w1) merge to 11 ≡ 0 and are
	// dropped, while C4 side c keeps its single non-cancelling w2 term.
	got, err := s.GetDefinition("dup", 1)
	if err != nil {
		t.Fatal(err)
	}
	if len(got.Constraints[1].A) != 0 {
		t.Fatalf("C2 side a should have merged to zero and been dropped, got %+v", got.Constraints[1].A)
	}
	if len(got.Constraints[3].C) != 1 || got.Constraints[3].C[0] != (Term{Wire: 2, Coeff: "1"}) {
		t.Fatalf("C4 side c must keep its single non-cancelling term, got %+v", got.Constraints[3].C)
	}
}

func bigPow10(n int64) *big.Int {
	return new(big.Int).Exp(big.NewInt(10), big.NewInt(n), nil)
}

package zkcircuit

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"strconv"
	"unicode/utf8"
)

// Saved circuit records used to be read and field-checked twice: once while
// the committed envelope was tokenized to reject a repeated object key
// (scanCircuitArray) and again while each circuits element was decoded into a
// persistCircuit (persistCircuit.UnmarshalJSON). Each pass gathered the
// record's member keys on its own and carried its own copy of the object,
// required-field and duplicate-key rules, so the judgment of what one
// committed circuit record may look like lived in two places that had to
// agree by construction.
//
// This file is now the single home of a saved circuit record's reading rules:
// the persistCircuit shape, the exact member spellings it accepts
// (name / version / constraints / public_inputs / private_inputs / frozen /
// description, plus the one optional definition), the strict scalar typing
// and the name exact-readback rule, together with one per-record reading
// engine (readCircuitRecord) both read passes drive. The directory scan and
// the single-record decode hence tokenize one record once and judge its keys
// and structure through the same code, which also covers two byte-identical
// member keys — a case a post-decode member map could not see on its own.
//
// Circuit fields are stricter than envelope and job fields: they are
// recognized ONLY under their exact lowercase wire spellings. Keys reach
// every rule below already JSON-unescaped, so a key written with a \uXXXX
// escape is judged on its decoded spelling, but no letter-case folding is
// applied — "FROZEN", "Name" and a long-s lookalike such as "frozeſ" are all
// ordinary unknown fields and corrupt the read the same way "note" does.
//
// Only the reading of saved circuit records is consolidated here. The public
// behavior — which values load, which are refused, how the failure is located
// and in what order findings surface — is unchanged; the commands, the Go
// entry points and the on-disk format stay as they were. In particular the
// two read passes keep their historical division of labor and precedence
// because an open always runs the directory scan before the typed decode: the
// scan owns structural findings and exact repeated keys (readCircuitRecord as
// driven by scanCircuitArray) over every record first, while the typed decode
// owns unknown fields, the per-field required/type checks, the name
// exact-readback rule and the definition decode (decodeCircuit).

type persistCircuit struct {
	Name          string             `json:"name"`
	Version       int                `json:"version"`
	Constraints   int                `json:"constraints"`
	PublicInputs  int                `json:"public_inputs"`
	PrivateInputs int                `json:"private_inputs"`
	Frozen        bool               `json:"frozen"`
	Description   string             `json:"description"`
	Definition    *persistDefinition `json:"definition,omitempty"`
}

// persistCircuitFields are the eight fields a committed circuit record may
// carry, under their exact (standard lowercase) wire spellings. Seven are
// required with the exact JSON type the writer emits; definition alone is
// optional (absent or null both mean the legacy counts-only state).
var persistCircuitFields = []string{
	"name", "version", "constraints", "public_inputs", "private_inputs",
	"frozen", "description", "definition",
}

// storedRecordShape is the shared strict-JSON rule set (definition_schema.go)
// tagged for committed data: every structural failure in a stored circuit or
// job record is data corruption, never a bad request.
var storedRecordShape = jsonShape{fail: corruptf}

// circuitMember is one member of a saved circuit record as seen during the
// single per-record pass: its already-JSON-unescaped key and its raw value.
type circuitMember struct {
	key   string
	value json.RawMessage
}

// readCircuitRecord consumes exactly one circuit record value the decoder is
// positioned at — including its opening token — and returns the members. The
// two passes drive it with a different key rule, so one tokenization serves
// both historical tiers:
//
//   - The directory scan passes allowedFields == nil: it does not judge which
//     keys are valid, only structure and a repeated key of ANY spelling. That
//     matches the old envelope scan, which attributed a repeated member to the
//     record whether or not the name was known.
//   - The typed decode passes the eight allowed spellings: at each key
//     position an unknown spelling is named first and a repeated allowed key
//     second, in document order — the precedence of the old strict member
//     walk (so an unknown member appearing before another key's second
//     occurrence is named as unknown, and an unknown key appearing twice is
//     named as unknown rather than duplicate).
//
// In both tiers the key judgment happens before that occurrence's value is
// decoded, the point at which both old passes rejected, so a malformed value
// following the offending key never substitutes a syntax error. Every other
// token is consumed unless the record is damaged. A null element or a
// non-object element is structural damage named by positional. positional is
// the name used to locate the record: the directory scan passes
// "circuit record #<1-based index>", the typed decode passes
// "stored circuit record".
//
// Member values are captured whole without descending: a nested value such as
// the constraint definition owns its own (more precise) strict decoder
// during the typed decode.
func readCircuitRecord(dec *json.Decoder, positional string, allowedFields []string) ([]circuitMember, error) {
	open, err := dec.Token()
	if err != nil {
		return nil, corruptf("%s is not valid JSON: %v", positional, err)
	}
	if open == nil {
		return nil, corruptf("%s must be a JSON object, not null", positional)
	}
	if open != json.Delim('{') {
		return nil, corruptf("%s must be a JSON object", positional)
	}

	var allowed map[string]bool
	if allowedFields != nil {
		allowed = make(map[string]bool, len(allowedFields))
		for _, f := range allowedFields {
			allowed[f] = true
		}
	}
	var members []circuitMember
	seen := make(map[string]bool)
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return nil, corruptf("%s is not valid JSON: %v", positional, err)
		}
		key, ok := keyTok.(string)
		if !ok {
			return nil, corruptf("%s is not valid JSON", positional)
		}
		// Keys arrive already JSON-unescaped, so a key spelled through a
		// \uXXXX escape is judged on its decoded spelling. The typed tier
		// names an unknown spelling ahead of a repetition; the scan tier only
		// sees repetitions. Both judgments pre-date the value decode, as they
		// always did.
		if allowed != nil && !allowed[key] {
			return nil, corruptf("%s has unknown field %q", positional, key)
		}
		if seen[key] {
			return nil, corruptf("%s contains duplicate field %q", positional, key)
		}
		seen[key] = true
		var value json.RawMessage
		if err := dec.Decode(&value); err != nil {
			return nil, corruptf("%s is not valid JSON: %v", positional, err)
		}
		members = append(members, circuitMember{key: key, value: value})
	}
	if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
		return nil, corruptf("%s is not valid JSON", positional)
	}
	return members, nil
}

// scanCircuitArray consumes one "circuits" value positioned at its opening
// bracket and reads every record through the shared per-record engine in
// scan mode (no allowed-field list), which names each structural problem or
// repeated key before the scan moves on. It is the directory-wide pre-check
// counterpart of decodeCircuit and exists so a structural problem inside one
// circuit is attributed to that record by its 1-based position rather than to
// an opaque "circuits" element index. A null array stays the pre-existing
// "no records" reading.
func scanCircuitArray(dec *json.Decoder) error {
	tok, err := dec.Token()
	if err != nil {
		return corruptf("data file envelope field \"circuits\" is not valid JSON: %v", err)
	}
	if tok == nil { // null: json.Unmarshal would produce no records
		return nil
	}
	if tok != json.Delim('[') {
		return corruptf("data file envelope field \"circuits\" must be an array")
	}
	index := 0
	for dec.More() {
		index++
		if _, err := readCircuitRecord(dec, fmt.Sprintf("circuit record #%d", index), nil); err != nil {
			return err
		}
	}
	if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
		return corruptf("data file envelope field \"circuits\" is not valid JSON")
	}
	return nil
}

// Strict decoding of committed circuit records.
//
// A circuit record in data.json must name each of name, version, constraints,
// public_inputs, private_inputs, frozen and description exactly once, with
// the exact JSON type the writer emits (string / integer / integer / integer
// / integer / boolean / string). A missing key, a null, a wrong type or a
// repeated key is data corruption and refuses the whole directory read: a
// missing or null frozen flag must not silently read as false (turning a
// frozen version back into an editable draft), and a repeated key must not
// resolve to its last value. An explicit 0, false or "" is an ordinary value
// and stays legal. The definition member remains the one optional field: it
// may be absent or null (the legacy counts-only state, which still compiles
// no further than "constraint definition missing"); when present it goes
// through the strict persistDefinition decoder, keeping the constraint order,
// input layout and compiled hash of defined versions intact.
//
// The name field carries one rule beyond shape: its raw JSON string token
// must denote its value exactly — valid UTF-8 in the literal portions and no
// unpaired \uXXXX surrogate escapes (checkStoredStringEncoding). Both damage
// shapes decode to U+FFFD replacement characters under encoding/json, which
// would rename the circuit on read; they are data corruption, and the whole
// directory read is refused. Only the name is judged this way; every other
// field keeps the ordinary decoding rules.
//
// Only shape is judged here. The domain rules (non-blank name, positive
// version and constraint count, non-negative input counts) keep being
// re-checked by validateEnvelope.

func (c *persistCircuit) UnmarshalJSON(raw []byte) error {
	const what = "stored circuit record"
	return decodeCircuit(raw, what, c)
}

// decodeCircuit reads one saved circuit record from raw through the shared
// engine and fills out. what is the generic name for a record located
// positionally; the envelope read prefixes it with the record index when it
// re-tags the error.
//
// Findings surface in the fixed order the two historical passes produced
// together: the object gate and trailing data, then the first unknown or
// repeated member in document order (an unknown spelling is named before a
// repetition at the same key position, exactly as the old strict member walk
// ordered it), then the field-by-field required/type checks with the name
// encoding rule right after the name string read, and only then the optional
// definition's own decode.
func decodeCircuit(raw []byte, what string, out *persistCircuit) error {
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 {
		return corruptf("%s must be a JSON object", what)
	}
	dec := json.NewDecoder(bytes.NewReader(trimmed))
	memberList, err := readCircuitRecord(dec, what, persistCircuitFields)
	if err != nil {
		return err
	}

	// A single complete object is the whole record. Unknown and repeated
	// members were already rejected during the single tokenization above, in
	// the old strict-member order (unknown before repetition, in document
	// order); this trailing-data check follows that gate, exactly as before.
	// At open the directory scan already guarantees it; the check keeps the
	// single-record decoder self-contained.
	if _, err := dec.Token(); err != io.EOF {
		return corruptf("%s is not valid JSON: trailing data after the object", what)
	}

	var c persistCircuit

	// The members are the allowed spellings without repeats, so the strict
	// required/scalar reads can address them by name.
	members := make(map[string]json.RawMessage, len(memberList))
	for _, m := range memberList {
		members[m.key] = m.value
	}

	requireString := func(key string, dst *string) error {
		v, err := storedRecordShape.require(members, key, what)
		if err != nil {
			return err
		}
		s, err := storedRecordShape.string(v, what+" field "+strconv.Quote(key))
		if err != nil {
			return err
		}
		*dst = s
		return nil
	}
	requireInt := func(key string, dst *int) error {
		v, err := storedRecordShape.require(members, key, what)
		if err != nil {
			return err
		}
		n, err := storedRecordShape.int(v, what+" field "+strconv.Quote(key))
		if err != nil {
			return err
		}
		*dst = n
		return nil
	}

	if err := requireString("name", &c.Name); err != nil {
		return err
	}
	// The name is the version's identity and must read back as the exact
	// value that was committed. encoding/json silently rewrites both invalid
	// UTF-8 bytes and unpaired \uXXXX surrogate escapes to U+FFFD, so the
	// decoded string alone cannot tell a damaged name apart from one that
	// legitimately contains "�". Judge the raw JSON token instead.
	if err := checkStoredStringEncoding(members["name"], what+` field "name"`, "committed name"); err != nil {
		return err
	}
	if err := requireInt("version", &c.Version); err != nil {
		return err
	}
	if err := requireInt("constraints", &c.Constraints); err != nil {
		return err
	}
	if err := requireInt("public_inputs", &c.PublicInputs); err != nil {
		return err
	}
	if err := requireInt("private_inputs", &c.PrivateInputs); err != nil {
		return err
	}
	frozenRaw, err := storedRecordShape.require(members, "frozen", what)
	if err != nil {
		return err
	}
	c.Frozen, err = storedRecordShape.bool(frozenRaw, what+" field "+strconv.Quote("frozen"))
	if err != nil {
		return err
	}
	if err := requireString("description", &c.Description); err != nil {
		return err
	}

	// definition is the only optional member: absent or null both mean the
	// counts-only legacy state.
	if defRaw, present := members["definition"]; present {
		if string(bytes.TrimSpace(defRaw)) != "null" {
			var def persistDefinition
			if err := json.Unmarshal(defRaw, &def); err != nil {
				var se StoreError
				if errors.As(err, &se) {
					return err // already reported as data corruption
				}
				return corruptf("%s field %s is not a valid constraint definition: %v", what, strconv.Quote("definition"), err)
			}
			c.Definition = &def
		}
	}

	*out = c
	return nil
}

// checkStoredStringEncoding enforces an identity field's exact-readback rule
// on the raw JSON string token of a committed value (a circuit record's name,
// a job record's id). The string has already been decoded by the strict
// member read, so the token is known to be one complete, well-formed JSON
// string; this walk judges only what that decode silently repairs:
//
//   - invalid UTF-8 bytes in the literal (unescaped) portions — a lone
//     continuation byte, a truncated multi-byte character, an overlong
//     form — which encoding/json rewrites to U+FFFD, and
//   - \uXXXX escapes forming an unpaired surrogate — a high surrogate not
//     immediately followed by its low-surrogate escape, or a low surrogate
//     standing alone — which are rewritten to U+FFFD the same way.
//
// Both would make the record read back under a different value than the bytes
// on disk carry, so the record is data corruption rather than a value that
// legitimately decodes to a replacement character it never had. noun is the
// word naming the value in diagnostics ("committed name" / "committed job
// id"); what locates the record and field, e.g.
// `stored circuit record field "name"` or `stored job record "j1" field
// "id"`. A legal surrogate pair decodes to its astral character, an actually
// committed "�" (written directly or as a U+FFFD escape) is an ordinary
// value, and the literal six characters "\uD800" — written with an escaped
// backslash — carry no escape at all: all three keep their exact value.
func checkStoredStringEncoding(raw json.RawMessage, what, noun string) error {
	token := bytes.TrimSpace(raw)
	// The token is a complete JSON string (the strict string read above
	// succeeded), so every escape is well-formed and the walk stays in
	// bounds; only the replacement-prone content is judged.
	for i := 1; i < len(token)-1; {
		c := token[i]
		if c == '\\' {
			if token[i+1] != 'u' {
				i += 2 // a simple escape: \" \\ \/ \b \f \n \r \t
				continue
			}
			code, _ := strconv.ParseUint(string(token[i+2:i+6]), 16, 32)
			switch {
			case code >= 0xD800 && code <= 0xDBFF:
				// A high surrogate is whole only when its low-surrogate
				// escape follows immediately.
				if i+12 <= len(token) && token[i+6] == '\\' && token[i+7] == 'u' {
					lo, _ := strconv.ParseUint(string(token[i+8:i+12]), 16, 32)
					if lo >= 0xDC00 && lo <= 0xDFFF {
						i += 12
						continue
					}
				}
				return corruptf("%s contains an unpaired high surrogate escape (\\u%04X); the %s would not read back unchanged", what, code, noun)
			case code >= 0xDC00 && code <= 0xDFFF:
				return corruptf("%s contains an unpaired low surrogate escape (\\u%04X); the %s would not read back unchanged", what, code, noun)
			}
			i += 6
			continue
		}
		if c < utf8.RuneSelf {
			i++
			continue
		}
		r, size := utf8.DecodeRune(token[i:])
		if r == utf8.RuneError && size == 1 {
			return corruptf("%s contains invalid UTF-8 bytes; the %s would not read back unchanged", what, noun)
		}
		i += size
	}
	return nil
}

